sed -i 's|const uMatch = fullBlockText.match(/\\\[U\\\]\\s*([A-D])[\\.\\)]?\\s*.*\\\[\\/U\\\]/i) || fullBlockText.match(/\\\[U\\\]\\s*([A-D])[\\.\\)]?\\s*\\\[\\/U\\\]/i);|let uMatch = fullBlockText.match(/\\[U\\]\\s*([A-D])[\\.\\)]?\\s*.*\\[\\/U\\]/i) || fullBlockText.match(/\\[U\\]\\s*([A-D])[\\.\\)]?\\s*\\[\\/U\\]/i);\n      if (!uMatch) {\n        const aIdx = textRemainderWithU.indexOf("A");\n        const bIdx = textRemainderWithU.indexOf("B");\n        const cIdx = textRemainderWithU.indexOf("C");\n        const dIdx = textRemainderWithU.indexOf("D");\n        const uIdx = textRemainderWithU.indexOf("[U]");\n        if (uIdx !== -1) {\n          if (dIdx !== -1 \&\& uIdx > dIdx) uMatch = [null, "D"];\n          else if (cIdx !== -1 \&\& uIdx > cIdx) uMatch = [null, "C"];\n          else if (bIdx !== -1 \&\& uIdx > bIdx) uMatch = [null, "B"];\n          else if (aIdx !== -1 \&\& uIdx > aIdx) uMatch = [null, "A"];\n        }\n      }|g' src/lib/wordParser.ts
